 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, color, texture, mix, smoothstep, pow, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const group = new THREE.Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const atlasRegion = config.intent?.visualSpec?.atlasRegion ?? config.atlasRegion;
  const rectW = atlasRegion?.sourceRect?.w ?? 512;
  const rectH = atlasRegion?.sourceRect?.h ?? 320;
  const aspect = rectW / rectH;

  const height = 1.0;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial();

  const buildColorNode = (tex = null) => {
    const vUV = uv();

    const gradT = pow(vUV.y, 0.75);
    const gradient = mix(color(surface), color(ink), gradT);

    let base;
    if (tex) {
      const metal = texture(tex).rgb;
      base = mix(metal, gradient, 0.45);
    } else {
      base = gradient;
    }

    const nUV = vUV.mul(900.0);
    const hval = fract(sin(dot(nUV, vec2(12.9898, 78.233))) * 43758.5453);
    const grain = mix(base, color(paper), hval.mul(0.035));

    const strip = smoothstep(0.94, 0.98, vUV.y);
    return mix(grain, color(accent), strip.mul(0.9));
  };

  material.colorNode = buildColorNode();

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  let loadedTexture = null;
  const timelines = [];

  group.userData._alive = true;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((tex) => {
        if (!group.userData._alive) {
          tex.dispose();
          return;
        }
        loadedTexture = tex;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(2.0, 2.0);
        tex.colorSpace = THREE.SRGBColorSpace;
        material.colorNode = buildColorNode(tex);
        material.needsUpdate = true;
      })
      .catch(() => {});
  }

  group.userData.handlers = {
    pointerenter: () => {},
    pointerleave: () => {},
    pointerdown: () => {},
    pointerup: () => {},
    click: () => {}
  };

  group.userData.cleanup = () => {
    group.userData._alive = false;
    timelines.forEach((tl) => tl?.kill());
    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
    geometry.dispose();
    material.dispose();
  };

  return group;
}
